<?php

namespace App\Http\Requests;

use App\Http\Requests\Concerns\ValidatesAccountRoles;
use App\Models\User;
use Illuminate\Contracts\Validation\ValidationRule;
use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rules\Password;
use Illuminate\Validation\Validator;

/**
 * Validates + authorizes creating a user account from the "Gestión de
 * usuarios" panel. Passwords are never auto-generated by the system — the
 * Administrador operating the panel must type one here, same "no default
 * password" principle as the existing console commands
 * (CreateZoneChiefCommand / CreateEstacionAccountCommand), just via a web
 * form instead of a CLI prompt.
 */
class StoreUserRequest extends FormRequest
{
    use ValidatesAccountRoles;

    public function authorize(): bool
    {
        return $this->user()?->can('create', User::class) ?? false;
    }

    protected function prepareForValidation(): void
    {
        $this->normalizeAccountInput();
    }

    /**
     * @return array<string, ValidationRule|array<mixed>|string>
     */
    public function rules(): array
    {
        return [
            'name' => ['required', 'string', 'max:255'],
            'email' => ['required', 'string', 'email', 'max:255', 'unique:users,email'],
            'password' => ['required', 'confirmed', Password::defaults()],
        ] + $this->roleRules();
    }

    /**
     * @return array<int, \Closure(Validator): void>
     */
    public function after(): array
    {
        return [
            fn (Validator $validator) => $this->validateExclusiveRoles($validator),
        ];
    }
}
